'use strict';

var xorshift32 = require( './../lib' );

// Generate normalized pseudorandom numbers in [0, 1)...
console.log( '\nUsing default instance (normalized):' );
var i;
for ( i = 0; i < 10; i++ ) {
	console.log( xorshift32.normalized() );
}

// Create a new PRNG and use the normalized method...
var seed = 5678;
var rand = xorshift32.factory({
	'seed': seed
});

console.log( '\nUsing factory instance with seed %d (normalized):', seed );
for ( i = 0; i < 10; i++ ) {
	console.log( rand.normalized() );
}

// Compare raw vs normalized output...
console.log( '\nComparing raw vs normalized (first 5 values):' );
var rng1 = xorshift32.factory({
	'seed': 999
});
var rng2 = xorshift32.factory({
	'seed': 999
});

for ( i = 0; i < 5; i++ ) {
	console.log( 'Raw: %d, Normalized: %f', rng1(), rng2.normalized() );
}
